<?php use Hls\Http\View as V; ?><section class="panel"><a class="button" href="<?= $this->url('/inventory/report-csv') ?>">Export CSV Stok</a></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Cabang</th><th>Gudang</th><th>Barang</th><th>Satuan</th><th>Stok Fisik</th><th>Dicadangkan</th><th>Tersedia</th></tr></thead><tbody><?php foreach($stocks as $r): $physical=(float)$r['stock_qty'];$reserved=(float)($r['reserved_qty']??0); ?><tr><td><?= V::escape($r['branch_code']) ?></td><td><?= V::escape($r['warehouse_code']) ?></td><td><?= V::escape($r['item_code'].' - '.$r['item_name']) ?></td><td><?= V::escape($r['unit_name']) ?></td><td><?= number_format($physical,3,',','.') ?></td><td><?= number_format($reserved,3,',','.') ?></td><td><?= number_format($physical-$reserved,3,',','.') ?></td></tr><?php endforeach ?><?php if(!$stocks): ?><tr><td colspan="7" class="empty-state">Belum ada data stok.</td></tr><?php endif ?></tbody></table></div></section>
